"""
    Indent a string by adding indent after each newline.
    :param string: The string to indent
    :param indent: The string to use as indentation
    :param include_first: Also indent the first line of the string (before the first newline)
    :param include_last: If the string ends on a newline, also add an indent after that.
    :return: A new string.
    """
def indent_string(
    string: Any,
    indent: Any = '  ',
    include_first: Any = True,
    include_last: Any = False
) -> object {
    base = string.replace('\n', ('\n' + indent));
    if include_first {
        base = indent + base;
    }
    if (not include_last and base.endswith(('\n' + indent))) {
        base = base[:-len(indent)];
    }
    return base;
}

"""
    Gets average if there are values, otherwise 0
    """
def get_average(metrics: Any) -> object {
    avg = 0;
    valid_count = 0;
    for class_name in metrics.keys() {
        if (metrics[class_name] is not None) {
            avg += metrics[class_name];
            valid_count += 1;
        }
    }
    if (valid_count > 0) {
        return (avg / valid_count);
    } else {
        return None;
    }
}

